// Custom Timeline Feature
.timeline {
  --line: 10px;
  --mid: 84px;
  --gap: 3rem;
  --dot: 14px;
  --accent: #ffcc00;
  --muted: #000;
  --lead: clamp(140px, 24vw, 572px);  /* dashed length toward text */
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 var(--gap);
  position: relative;
  color: #000;
}
.timeline::before{
  content:"";
  position:absolute; inset:0 auto 0 50%;
  transform:translateX(-50%);
  width:var(--line); background:#000; border-radius:999px;
}
.timeline__list{list-style:none;margin:0;padding:0;}
.t-item{
  display:grid;
  grid-template-columns: 1fr var(--mid) 1fr;  /* left | middle | right */
  margin: 0; /*5rem 0; */
  position:relative;
}

.t-item.right span.t-badge {
  left: calc(50% + var(--lead));
  transform: translate(-50%, -50%);   
}  

.t-item.left span.t-badge {
  right: calc(50% + var(--lead));
  transform: translate(50%, -50%);
}  

.t-item.right .t-content {
  text-align: right;
}  

.t-item.right .t-content .t-copy {
  margin-left:auto;
  margin-right:0;
}  

/* TOP end-cap */
.timeline__cap{
  position:absolute; top:0; left:50%;
  transform:translate(-50%, -60%);
  width:28px; height:28px; background:#fff3bf;
  border:6px solid #000; border-radius:50%;
  z-index:4;
}

.timeline__cap i{
  position:absolute; top:50%; left:50%;
  width:8px; height:8px; background:#000; border-radius:50%;
  transform:translate(-50%,-50%);
}

.timeline__endcap {
    img {
        position: absolute;
        bottom: -40px;
        left: 50%;
        transform: translate(-50%, -50%);
    }
}
  
/* content blocks */
.t-content{max-width:460px;padding-top:50px;padding-bottom:50px;}
.t-item.left  .t-content{grid-column:1/2;}
.t-item.right .t-content{grid-column:3/4;}
.t-year{font-weight:800;font-style:italic;font-size:clamp(1.8rem,2.5vw,3rem);margin:0 0 .25rem;}
.t-title{font-weight:700;font-size:1.75rem;margin:0 0 .5rem;}
.t-copy{color:var(--muted);margin:0;line-height:1.55;max-width:42ch;}

/* middle column (dot + badge + dashed lead) */
.t-mid{grid-column:2/3; position:relative; height:140px;}
.t-dot{
  position:absolute; top:0; left:50%; transform:translate(-50%,-50%);
  width:var(--dot); height:var(--dot); background:#ffeaa3; border:4px solid #000; border-radius:50%; z-index:3;
}
.t-badge{
  position:absolute; /* bottom:0; left:50%; transform:translate(-50%,50%); */
  width:84px; height:84px; border-radius:50%; background:#fff; box-shadow:0 0 0 8px var(--accent);
  display:grid; place-items:center; font-size:32px; line-height:1; z-index:2;
}

/* REAL element for dashed connector + end dot */
.t-lead{
  position:absolute; top:0; height:0; border-top:2px dashed #000; z-index:2;
  width:var(--lead);
}
.t-end{
  position:absolute; top:0; width:10px; height:10px; border:2px solid #000; border-radius:50%; background:#fff; z-index:2;
}

.t-item.left  .t-lead{ right:50%; }
.t-item.right .t-lead{ left:50%;  }
.t-item.left  .t-end{  right: calc(50% + var(--lead)); transform:translate(50%,-50%); }
.t-item.right .t-end{  left:  calc(50% + var(--lead)); transform:translate(-50%,-50%); }

