/*Blog Styles*/
.blog-post{display:grid;}
.two-col-blog{display:grid; grid-template-columns: auto auto; column-gap:5em; align-items:center; padding:1em;}
.blog-image-curved{border-radius:30px; width:auto;}
//.blog-title{text-align:center;}
h1.blog-title{font-size:30px;}
.image-port{max-width:30em;}
.image-land{max-width:40em;}
.blog-thumbnail{max-width:95%; max-height:21em; max-width:35em; margin:0px 0px 5px 0px;}
/*Breakpoint for 1-col on Tablet and Mobile*/
@media (max-width:768px){
    .two-col-blog{display:grid; grid-template-columns: auto; align-items:center; padding:.5em;}
    .blog-image-curved{border-radius:30px; width:50%;}
}
